CREATE TABLE staff_users (id BIGINT AUTO_INCREMENT PRIMARY KEY, username VARCHAR(120) NOT NULL UNIQUE, password_hash VARCHAR(100) NOT NULL, name VARCHAR(100) NOT NULL, role VARCHAR(20) NOT NULL);
CREATE TABLE staff_sessions (id VARCHAR(36) PRIMARY KEY, staff_id BIGINT NOT NULL, refresh_hash VARCHAR(64) NOT NULL, expires_at TIMESTAMP(6) NOT NULL, CONSTRAINT fk_session_staff FOREIGN KEY (staff_id) REFERENCES staff_users(id));
ALTER TABLE payments ADD COLUMN request_key VARCHAR(64) UNIQUE;
